import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom matrix multiplication kernel for A^T * B without explicit transpose
matmul_transposed_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define THREADS_PER_BLOCK 256

__global__ void matmul_transposed_kernel(const float* __restrict__ A,
                                         const float* __restrict__ B,
                                         float* __restrict__ C,
                                         int M, int K, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    int row = bx * TILE_SIZE + tx;
    int col = by * TILE_SIZE + ty;

    float sum = 0.0;

    for (int t = 0; t < K; t += TILE_SIZE) {
        // Load A tile (transposed access)
        if (row < M && (t + ty) < K)
            As[tx][ty] = A[(t + ty) * M + row];
        else
            As[tx][ty] = 0.0;

        // Load B tile
        if (col < N && (t + tx) < K)
            Bs[tx][ty] = B[(t + tx) * N + col];
        else
            Bs[tx][ty] = 0.0;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[tx][k] * Bs[k][ty];
        }

        __syncthreads();
    }

    if (row < M && col < N)
        C[row * N + col] = sum;
}

torch::Tensor matmul_transposed_cuda(torch::Tensor A, torch::Tensor B) {
    int M = A.size(1);
    int K = A.size(0);
    int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    dim3 threads(TILE_SIZE, TILE_SIZE);
    dim3 blocks((M + TILE_SIZE - 1) / TILE_SIZE,
                (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_transposed_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K, N
    );

    return C;
}
"""

matmul_transposed_cpp = "torch::Tensor matmul_transposed_cuda(torch::Tensor A, torch::Tensor B);"

matmul_transposed = load_inline(
    name='matmul_transposed',
    cpp_sources=matmul_transposed_cpp,
    cuda_sources=matmul_transposed_source,
    functions=['matmul_transposed_cuda'],
    verbose=False,
    extra_cflags=['-O3'],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.custom_matmul = matmul_transposed.matmul_transposed_cuda

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.custom_matmul(A, B)
